import React, { useRef, Suspense, useState, useMemo, useEffect} from 'react';
import ReactPlayer from 'react-player';
import '../player.css'


const VideoRender = ({ data, videoIndex, playerRef}) => {
    const videoRef = useRef(null);

    // Memoize video element
    const videoElement = useMemo(() => {
        if (data) {
        return (
            <>
                {/* Show loader if video is not loaded */}
                {/* {!videoLoaded && (
                    <div>
                        <img src={logo} className='w-[5%] h-[5%]' alt="Loader" />
                    </div>
                )} */}
                {
                    data.map((videoLink, index) => (
                        <div className={`${videoIndex == index ? "" : "video-bg"} ${'player-wrapper'}`} >
                            <ReactPlayer
                            ref={playerRef.current[index]}
                            className='react-player'
                            playing muted loop playsinline
                            url={videoLink.redirectLink}
                            width='100%' height='100%'
                            config={{
                                playerOptions: {
                                    playsinline: true,
                            }
                            }}
                            >
                            </ReactPlayer>
                        </div>
                    ))
                }
            </>
        );
        }
        return null;
    }, [data, videoIndex]);

  return videoElement;
};

export default VideoRender;